<?php
// Define the calculus expression
$calculus = "∑∑∑∑∑∑∑∑∑∑∑∑∂∂∂∂∂∂∂∂∂∂∂∂∂∂∂∂∂∂∂∂∂∂∂∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈∈";
// Count the frequency of each symbol
