$partial_frequency = substr_count($calculus, '∂');
$element_frequency = substr_count($calculus, '∈');
// Display the frequency of each symbol
echo "Frequency of ∑: " . $sum_frequency . "<br>";
echo "Frequency of ∂: " . $partial_frequency . "<br>";
echo "Frequency of ∈: " . $element_frequency . "<br>";
// Determine the least commonly used symbol
$symbols = array('∑' => $sum_frequency, '∂' => $partial_frequency, '∈' => $element_frequency);
arsort($symbols);
