```
#include <iostream>
#include <armadillo>
#include <Eigen/Dense>
using namespace std;
using namespace arma;
using namespace Eigen;
int main()
{
    // Load data on temperature, human activity, volcanic activity, and solar radiation
    mat temperature = load("temperature.csv");
    mat human_activity = load("human_activity.csv");
    mat volcanic_activity = load("volcanic_activity.csv");
    mat solar_radiation = load("solar_radiation.csv");
    // Combine data into a single matrix
    mat data = join_horiz(temperature, human_activity);
    data = join_horiz(data, volcanic_activity);
    data = join_horiz(data, solar_radiation);
    // Normalize data to ensure equal weights for each factor
    data = normalise(data);
    // Split data into training and testing sets
    int n = data.n_rows;
    int m = data.n_cols;
    int train_size = n * 0.8;
    int test_size = n - train_size;
    mat train_data = data.submat(0, 0, train_size - 1, m - 1);
    mat test_data = data.submat(train_size, 0, n - 1, m - 1);
    // Use principal component analysis (PCA) to reduce dimensionality of data
    PCA<MatrixXd> pca(train_data);
    MatrixXd transformed_data = pca.transform(test_data);
    // Use linear regression to model the relationship between factors and global warming trends
    MatrixXd X = transformed_data.block(0, 0, test_size, m - 1);
    VectorXd y = transformed_data.col(m - 1);
    MatrixXd XtX = X.transpose() * X;
    VectorXd Xty = X.transpose() * y;
    VectorXd beta = XtX.colPivHouseholderQr().solve(Xty);
    // Calculate mean squared error (MSE) to evaluate model performance
    VectorXd y_pred = X * beta;
    double mse = (y - y_pred).squaredNorm() / test_size;
    // Print results
    cout << "Coefficients: " << beta.transpose() << endl;
    cout << "Mean squared error: " << mse << endl;
    return 0;
}
```
This code loads data on temperature, human activity, volcanic activity, and solar radiation from CSV files, combines the data into a single matrix, normalizes the data to ensure equal weights for each factor, and splits the data into training and testing sets. It then uses principal component analysis (PCA) to reduce the dimensionality of the data, and linear regression to model the relationship between factors and global warming trends. Finally, it calculates the mean squared error (MSE) to evaluate the performance of the model.

